private void drawHudNoSelectionHint(Canvas canvas, float ox, float oy, float s) {
    String hint = MainActivity.this.uiText("SELECT UNIT OR BUILDING", "ВЫБЕРИТЕ ЮНИТ ИЛИ ЗДАНИЕ");
    String[] words = hint.split(" ");
    float maxW = 72.0f * s;
    this.textPaint.setTextAlign(Paint.Align.LEFT);
    this.textPaint.setFakeBoldText(false);
    this.textPaint.setTextSize(3.65f * s);
    this.textPaint.setColor(Color.rgb(DuneHackR82cRazorCombatAudit.DAMAGE_WORDS, 154, 168));
    String first = "";
    String second = "";
    for (String word : words) {
        if (word != null && !word.isEmpty()) {
            String test = first.isEmpty() ? word : first + " " + word;
            if (second.isEmpty() && this.textPaint.measureText(test) <= maxW) {
                first = test;
            } else {
                second = second.isEmpty() ? word : second + " " + word;
            }
        }
    }
    float x = (274.0f * s) + ox;
    if (!first.isEmpty()) {
        canvas.drawText(first, x, (40.5f * s) + oy, this.textPaint);
    }
    if (!second.isEmpty()) {
        int save = canvas.save();
        canvas.clipRect(x, (41.0f * s) + oy, (346.0f * s) + ox, (51.5f * s) + oy);
        canvas.drawText(second, x, (47.0f * s) + oy, this.textPaint);
        canvas.restoreToCount(save);
    }
}

private void drawHudCargoBar(Canvas canvas, float ox, float oy, float s, float x, float y, float width, float height, int cargo) {
