    this.terrainPaint.setColor(Color.rgb(222, 137, MainActivity.MENU_ACTION_DIAGNOSTICS_SHOW_FPS));
    canvas.drawRect(left + s, top + s, left + s + (Math.max(0.0f, (width - 2.0f) * s) * ratio), bottom - s, this.terrainPaint);
    this.linePaint.setStyle(Paint.Style.STROKE);
    this.linePaint.setStrokeWidth(Math.max(1.0f, s));
    this.linePaint.setColor(Color.rgb(235, 190, 92));
    canvas.drawRect(left, top, right, bottom, this.linePaint);
}

